+    "filters": ["crash_date year is 2013 through 2025", "crash_date is nonmissing", "number_of_motorist_killed is nonmissing"],
+    "years": "calendar years 2013-2025 inclusive, assigned from crash_date",
+    "grouping": "crash_date calendar year"
+  }
+}
*** Add File: out/plan_2.json
+{
+  "initial_plan": {
+    "can_answer_question": "partly: the data cannot measure motorist fatality risk per mile because it contains no miles-driven or vehicle-miles-traveled exposure; it can show the share of reported crash deaths that were motorists",
+    "metric": "annual share of all reported crash deaths that were motorist deaths: sum(number_of_motorist_killed) / sum(number_of_persons_killed)",
+    "denominator": "sum of number_of_persons_killed in the same year among records with both death fields nonmissing",
