+    "filters": ["crash_date year is 2013 through 2025", "crash_date is nonmissing", "number_of_motorist_killed and number_of_persons_killed are both nonmissing"],
+    "years": "calendar years 2013-2025 inclusive, assigned from crash_date",
+    "grouping": "crash_date calendar year"
+  }
+}
